import sys

def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    if r == 1 and c == 1:
        print(0)
        return
    W = c + 2
    g = [3] * ((r + 2) * W)
    for i in range(r):
        base = (i + 1) * W + 1
        for j in range(c):
            g[base + j] = int(data[2 + i * c + j])
    start = W + 1
    goal = r * W + c
    for t in range(3):
        seen = bytearray(len(g))
        seen[start] = 1
        stack = [start]
        found = False
        while stack:
            u = stack.pop()
            if u == goal:
                found = True
                break
            for v in (u - 1, u + 1, u - W, u + W):
                if not seen[v] and g[v] <= t:
                    seen[v] = 1
                    stack.append(v)
        if found:
            print(t)
            return

